.param W_xm4=20u    L_xm4=1u
.param W_xm5=10u    L_xm5=1u
.param W_xm6=10u    L_xm6=1u
.param W_xm7=10u    L_xm7=1u
.param W_xm8=10u    L_xm8=1u
.param W_xmsu1=10u  L_xmsu1=10u
.param W_xm9=20u    L_xm9=2u
.param W_xm10=20u   L_xm10=1u
.param W_xm11=20u   L_xm11=1u
.param W_xm12=10u   L_xm12=1u
.param W_xm13=10u   L_xm13=1u
.param W_xm14=20u   L_xm14=1u
.param W_xm15=10u   L_xm15=1u
.param W_xm16=10u   L_xm16=1u
.param W_xm17=10u   L_xm17=1u
.param W_xm18=10u   L_xm18=1u
